import {
  PROPOSAL_GENERIC,
  GROUP_NAME_MAX_CHAR,
  GROUP_DESCRIPTION_MAX_CHAR,
  GROUP_MINCOME_MAX
} from '../../../../frontend/model/contracts/shared/constants.js'
